insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$goioxim$q$, $q$https://www.diariomunicipal.com.br/amp/materia/80117BA7 (Lei 712/2021, Diário Oficial dos Municípios do Paraná ed. 2331, 19/08/2021)$q$, $q$Atos oficiais do município: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM). Texto obtido no Diário Oficial dos Municípios do Paraná (AMP).$q$, 33, $q$Lei 712/2021, art. 2º: 36 ruas (a lista é 'em especial', exemplificativa das vias centrais; vale nas ruas nomeadas). Desvio obrigatório pela Rua Moacir Júlio Silvestre (art. 3º). A Portaria 63/2009 (Anexo I) citada no art. 1º não foi lida. A exceção do § 2º (abastecimento do comércio local, entregas eventuais a cidadãos, veículos da Prefeitura) é ampla e não modelável.$q$);
